head.script:
scwin.screenId = "jldfil71501";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_DigitalSelectSub", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }, { id: "btn_DigitalExcelDownload", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }, { id: "btn_DigitalExcelUploadPop", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71501' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71501.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_lastApplCnt_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_lastApplCnt_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_lastApplCnt_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71501.slc_lastApplCnt_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["bzProcsNo"] != null && r["bzProcsNo"] !== '' && r["applStatusCd"] !== '02') { if (typeof scwin.digitalApplDel === 'function') { await scwin.digitalApplDel(r["bzProcsNo"], r["applStatusCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.digitalApplDel (열 삭제)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.digitalApplDel'); } return; }
        if (typeof scwin.digitalMst === 'function') { await scwin.digitalMst(r["isuCd"], r["bzProcsNo"], r["applStatusCd"], r["lastSaveStatCd"], r["rsnTabNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.digitalMst (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.digitalMst'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_DigitalSelectSub_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_DigitalSelectSub_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_DigitalSelectSub_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_DigitalSelectSub()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71501.btn_DigitalSelectSub_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_DigitalExcelDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_DigitalExcelDownload_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_DigitalExcelDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_DigitalExcelDownload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71501.btn_DigitalExcelDownload_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_DigitalExcelUploadPop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_DigitalExcelUploadPop_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_DigitalExcelUploadPop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_DigitalExcelUploadPop('' + dma_readDataVO.get("listBzCd") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71501.btn_DigitalExcelUploadPop_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71501.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_digitalApplDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_digitalApplDel = async function () {
    const sbmOptions = {
        id: "tx_fn_digitalApplDel",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_digitalApplDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71501.tx_fn_digitalApplDel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_DigitalMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_DigitalMst = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalMst",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71501.tx_fn_DigitalMst" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/digital/DigitalList.do?method=searchList&listBzCd=0",
        ref: "dma_loadListReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71501.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_67").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.digitalApplDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo applStatusCd
 * @returns
 * @hidden N
*/
scwin.digitalApplDel = async function (bzProcsNo, applStatusCd) {
    /* sdd-asis-lifecycle:begin fn_digitalApplDel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (applStatusCd === '02') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!$c.lc.fn_isProcess('D')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'deleteList');
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    await scwin.tx_fn_digitalApplDel();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.digitalMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuCd bzProcsNo applStatusCd lastSaveStatCd rsnTabNo
 * @returns
 * @hidden N
*/
scwin.digitalMst = async function (isuCd, bzProcsNo, applStatusCd, lastSaveStatCd, rsnTabNo) {
    /* sdd-asis-lifecycle:begin fn_DigitalMst — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void("isuCd==" + isuCd + "bzProcsNo==" + bzProcsNo + "applStatusCd==" + applStatusCd + "lastSaveStatCd" + lastSaveStatCd + "rsnTabNo==" + rsnTabNo);
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'detailList');
    $c.util.getComponent('dma_SearchReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    if (applStatusCd === '03') {
        if (rsnTabNo !== '05') {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', Number(rsnTabNo));
        } else {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', 0);
        }
    } else {
        $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', lastSaveStatCd);
    }
    $c.util.getComponent('dma_SearchReq').set('applStatusCd', applStatusCd);
    await scwin.tx_fn_DigitalMst();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_67_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_67_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_67.page' }); } scwin.tx_load_list(); };
